import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gemm_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matmul(torch::Tensor A, torch::Tensor B);
"""

gemm_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// C(M,N) = A(M,K) * B(K,N), all row-major float32.
// B is viewed as (N,K) with stride (1,N) so the cute::gemm (M,K)x(N,K)->(M,N)
// "TN" form computes sum_k A(m,k) * B(k,n) exactly.
template <class TA, class TB, class TC>
__global__ static void
gemm_device(int M, int N, int K,
            TA const* __restrict__ A,
            TB const* __restrict__ B,
            TC*       __restrict__ C)
{
  using namespace cute;

  // Full tensors
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{})); // (M,K) row-major
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(Int<1>{}, N)); // (N,K) view of B^T
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{})); // (M,N) row-major

  // CTA tiling: 128x128 output tile, 8-wide K slices
  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<8>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,  X, _1>{}); // (128,8,K/8)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step< X, _1, _1>{}); // (128,8,K/8)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1, _1,  X>{}); // (128,128)

  // Shared memory staging buffers
  __shared__ TA smemA[128*8];
  __shared__ TB smemB[128*8];
  Tensor sA = make_tensor(make_smem_ptr(smemA), make_shape(Int<128>{}, Int<8>{}));
  Tensor sB = make_tensor(make_smem_ptr(smemB), make_shape(Int<128>{}, Int<8>{}));

  // Thread layouts (256 threads per CTA)
  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));

  // Global -> shared copy partitions
  Tensor tAgA = local_partition(gA, tA, threadIdx.x); // (4,1,K/8)
  Tensor tAsA = local_partition(sA, tA, threadIdx.x); // (4,1)
  Tensor tBgB = local_partition(gB, tB, threadIdx.x); // (4,1,K/8)
  Tensor tBsB = local_partition(sB, tB, threadIdx.x); // (4,1)

  // Compute partitions: each thread owns an 8x8 output micro-tile
  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1,  X>{}); // (8,8) (M,K)
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step< X, _1>{}); // (8,8) (N,K)
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1, _1>{}); // (8,8) (M,N)

  // Register accumulator
  Tensor tCrC = make_tensor<float>(shape(tCgC));
  clear(tCrC);

  // Mainloop over K tiles
  int K_TILE_MAX = size<2>(tAgA);
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    copy(tAgA(_,_,k_tile), tAsA);
    copy(tBgB(_,_,k_tile), tBsB);

    cp_async_fence();
    cp_async_wait<0>();
    __syncthreads();

    gemm(tCsA, tCsB, tCrC); // tCrC += tCsA * tCsB^T
    __syncthreads();
  }

  // Epilogue: write accumulators to global memory
  axpby(1.0f, tCrC, 0.0f, tCgC);
}

torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0) == K, "Inner dimensions must agree");
  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 8 == 0,
              "This kernel requires M,N divisible by 128 and K divisible by 8");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, N}, A.options());

  float const* ptrA = A_c.data_ptr<float>();
  float const* ptrB = B_c.data_ptr<float>();
  float*       ptrC = C.data_ptr<float>();

  dim3 dimBlock(256);
  dim3 dimGrid((M + 127) / 128, (N + 127) / 128);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_device<float, float, float><<<dimGrid, dimBlock, 0, stream>>>(
      M, N, K, ptrA, ptrB, ptrC);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_gemm_ext = load_inline(
    name="cute_square_matmul_ext",
    cpp_sources=gemm_cpp_decl,
    cuda_sources=gemm_cuda_src,
    functions=["matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Square matrix multiplication C = A * B implemented with a single
    cooperative tiled CuTe GEMM kernel (128x128 CTA tiles, K-slices of 8,
    shared-memory staging, per-thread 8x8 register accumulators).
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_gemm_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        return self._ext.matmul(A.contiguous(), B.contiguous())

